var i=[{title:`Die wichtigsten Variationen`,text:`Bei einer Split-Kniebeuge bleiben die Füße in versetzter Stellung stehen. Ein Ausfallschritt rückwärts macht bei jeder Wiederholung einen Schritt nach hinten, und ein Ausfallschritt vorwärts oder gehend bringt den Körper in eine neue Position. Ein Step-up hebt dich auf eine stabile Plattform, und eine Split-Kniebeuge mit erhöhtem hinterem Fuß macht die Übung schwerer. Die Variationen überschneiden sich, unterscheiden sich aber in den Gleichgewichtsanforderungen und darin, wie weit Knie und Hüfte wandern. Alle ergänzen zweibeinige Kniebeugen und Hüftbeugen gut.`},{title:`Grundtechnik`,text:`Nimm bei einer Split-Kniebeuge einen Stand, der breit genug ist, um sicher zu stehen, senke dich gerade nach unten ab, indem du Knie und Hüfte kontrolliert beugst, und komm dann über das Arbeitsbein wieder hoch. Halte den vorderen Fuß flach auf dem Boden und lass das Knie einem bequemen Weg folgen. Eine leichte Vorneigung des Oberkörpers kann normal sein. Die beste Schrittlänge hängt von deinen Körperproportionen und davon ab, wofür du trainierst.`},{title:`Gleichgewicht und Sicherheit`,text:`Halte dich beim Lernen mit einer Hand an einer Wand oder einem Geländer fest. Wenn die Übung zu einem Gleichgewichtstest wird, verkürze den Schritt, verringere die Tiefe oder nimm weniger Gewicht, bis es wieder kontrolliertes Krafttraining wird. Vermeide instabile Kisten und sehr hohe Stufen. Wenn die Bewegung immer wieder Gelenkschmerzen verursacht, höre auf oder wechsle zu einer anderen Übung.`},{title:`Die Seiten vergleichen`,text:`Beginne mit deiner unsichereren Seite und gleiche dann die Zahl guter Wiederholungen auf der anderen Seite an. Mache zum Beispiel zwei Sätze mit sechs Ausfallschritten rückwärts pro Bein mit einer Stütze. Kleine Unterschiede zwischen den Seiten bedeuten nicht, dass du verletzt bist, und mit der Zeit bessere Kontrolle ist ein gutes Ziel. Steigere dich, indem du zuerst die Stütze loslässt, dann Wiederholungen ergänzt und danach Widerstand hinzufügst.`}];var t=[{label:`ACE-Übungsbibliothek`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`},{label:`NSCA: Sicherheit und Grundlagen des Krafttrainings`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: Technik beim Krafttraining (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};